/**
 * Client-side image + PDF export for saved tool results.
 *
 * Draws a formatted "result card" onto a canvas. The same canvas can be
 * exported as a PNG image OR as a PDF document (single page, same
 * dimensions as the canvas). No external libraries — uses the native
 * Canvas 2D API.
 *
 * The card design is consistent across all 5 tools:
 *   - Dark header bar with Alkemos logo + tool name + date
 *   - Big primary number (the headline metric)
 *   - Secondary metrics in a 2-column grid
 *   - Footer with "Generated by Alkemos — alkemos.com" where
 *     "Alkemos" is the visible brand name and the .com is the site
 *     link (rendered as text in the image/PDF; clickable if the consumer
 *     embeds the PDF in an HTML page).
 *
 * Note: the brand name is "Alkemos" (one word, capitalized CamelCase)
 * as requested by the user — the site URL itself is alkemos.com.
 */

/**
 * Tool result payload as the card renderer consumes it: primitive fields
 * (interpolated into the card text) plus the string fields some rows print
 * directly. Extra fields tool pages send ride along untouched at runtime.
 */
export type ToolResultData = Record<string, string | number | undefined | null> & {
  category?: string;
  gender?: string;
  method?: string;
  date?: string;
};

type ExportArgs = {
  toolSlug: string;
  title: string;
  resultData: ToolResultData;
  isAr: boolean;
};

// Canvas dimensions (aspect 4:5, portrait — fits both PNG export and
// PDF page export at the same scale).
const W = 1080;
const H = 1350;

const COLORS = {
  bg: "#ffffff",
  cardBg: "#f5f5f7",
  darkBg: "#1d1d1f",
  primary: "#0071e3",
  text: "#1d1d1f",
  subtext: "#6e6e73",
  border: "#d2d2d7",
  white: "#ffffff",
};

const TOOL_META: Record<
  string,
  {
    nameAr: string;
    nameEn: string;
    /** Returns: { headline: string, sublabel: string, rows: [string, string][] } */
    format: (data: ToolResultData, isAr: boolean) => {
      headline: string;
      sublabel: string;
      rows: Array<[string, string]>;
    };
  }
> = {
  "calorie-calculator": {
    nameAr: "حاسبة السعرات الحرارية",
    nameEn: "Calorie Calculator",
    format: (d, isAr) => ({
      headline: `${d.target}`,
      sublabel: isAr ? "سعرة حرارية / يوم" : "calories / day",
      rows: [
        [isAr ? "BMR" : "BMR", `${d.bmr}`],
        [isAr ? "TDEE" : "TDEE", `${d.tdee}`],
        [isAr ? "بروتين" : "Protein", `${d.protein}g`],
        [isAr ? "كربوهيدرات" : "Carbs", `${d.carbs}g`],
        [isAr ? "دهون" : "Fat", `${d.fat}g`],
      ],
    }),
  },
  "bmi-calculator": {
    nameAr: "حاسبة BMI",
    nameEn: "BMI Calculator",
    format: (d, isAr) => ({
      headline: `${d.bmi}`,
      sublabel: isAr ? `(${d.category})` : `(${d.category})`,
      rows: [
        [isAr ? "الفئة" : "Category", d.category || "—"],
        [isAr ? "الوزن المثالي" : "Ideal weight", `${d.idealWeightMin}–${d.idealWeightMax} kg`],
        [isAr ? "الجنس" : "Gender", d.gender || "—"],
      ],
    }),
  },
  "macro-calculator": {
    nameAr: "حاسبة الماكروز",
    nameEn: "Macro Calculator",
    format: (d, isAr) => ({
      // Macro calculator sends result as { protein_g, carbs_g, fat_g, ... }
      // (see src/app/tools/macro-calculator/page.tsx) — accept both
      // _g-suffixed AND plain-name fields for safety.
      headline: `${d.calories || d.target || "—"}`,
      sublabel: isAr ? "سعرة حرارية / يوم" : "calories / day",
      rows: [
        [isAr ? "بروتين" : "Protein", `${d.protein_g ?? d.protein ?? "—"}g`],
        [isAr ? "كربوهيدرات" : "Carbs", `${d.carbs_g ?? d.carbs ?? "—"}g`],
        [isAr ? "دهون" : "Fat", `${d.fat_g ?? d.fat ?? "—"}g`],
      ],
    }),
  },
  "body-fat-calculator": {
    nameAr: "حاسبة الدهون",
    nameEn: "Body Fat Calculator",
    format: (d, isAr) => ({
      headline: `${d.bodyFat || d.bf || "—"}`,
      sublabel: isAr ? "% دهون" : "% body fat",
      rows: [
        [isAr ? "الفئة" : "Category", d.category || "—"],
        [isAr ? "كتلة الدهون" : "Fat mass", `${d.fatMass || "—"} kg`],
        [isAr ? "الكتلة الصافية" : "Lean mass", `${d.leanMass || "—"} kg`],
        [isAr ? "الطريقة" : "Method", d.method || "—"],
      ],
    }),
  },
  "water-tracker": {
    nameAr: "متتبع شرب الماء",
    nameEn: "Water Tracker",
    format: (d, isAr) => ({
      headline: `${d.consumed_ml ?? 0}`,
      sublabel: isAr ? `مل / ${d.goal_ml ?? 0} مل` : `ml / ${d.goal_ml ?? 0} ml`,
      rows: [
        [isAr ? "التاريخ" : "Date", d.date || "—"],
        [isAr ? "الهدف اليومي" : "Daily goal", `${d.goal_ml ?? "—"} ml`],
        [isAr ? "حجم الكوب" : "Cup size", `${d.cup_ml ?? "—"} ml`],
      ],
    }),
  },
};

function drawRoundedRect(
  ctx: CanvasRenderingContext2D,
  x: number,
  y: number,
  w: number,
  h: number,
  r: number,
) {
  ctx.beginPath();
  ctx.moveTo(x + r, y);
  ctx.lineTo(x + w - r, y);
  ctx.quadraticCurveTo(x + w, y, x + w, y + r);
  ctx.lineTo(x + w, y + h - r);
  ctx.quadraticCurveTo(x + w, y + h, x + w - r, y + h);
  ctx.lineTo(x + r, y + h);
  ctx.quadraticCurveTo(x, y + h, x, y + h - r);
  ctx.lineTo(x, y + r);
  ctx.quadraticCurveTo(x, y, x + r, y);
  ctx.closePath();
}

function wrapText(
  ctx: CanvasRenderingContext2D,
  text: string,
  maxWidth: number,
): string[] {
  const words = text.split(" ");
  const lines: string[] = [];
  let line = "";
  for (const w of words) {
    const test = line ? line + " " + w : w;
    if (ctx.measureText(test).width > maxWidth && line) {
      lines.push(line);
      line = w;
    } else {
      line = test;
    }
  }
  if (line) lines.push(line);
  return lines;
}

/**
 * Internal: draws the result card onto a canvas at dimensions W×H.
 * Returns the canvas so callers can convert it to PNG or PDF.
 */
function drawResultCanvas({
  toolSlug,
  title,
  resultData,
  isAr,
}: ExportArgs): HTMLCanvasElement {
  const meta = TOOL_META[toolSlug];
  if (!meta) throw new Error("Unknown tool slug: " + toolSlug);

  const canvas = document.createElement("canvas");
  canvas.width = W;
  canvas.height = H;
  const ctx = canvas.getContext("2d");
  if (!ctx) throw new Error("Canvas 2D not supported");

  // Set text direction (Arabic = RTL)
  ctx.direction = isAr ? "rtl" : "ltr";
  ctx.textAlign = isAr ? "right" : "left";

  // Background
  ctx.fillStyle = COLORS.bg;
  ctx.fillRect(0, 0, W, H);

  // === Header (dark band) ===
  ctx.fillStyle = COLORS.darkBg;
  drawRoundedRect(ctx, 60, 60, W - 120, 180, 32);
  ctx.fill();

  // Logo (Alkemos brand name)
  ctx.fillStyle = COLORS.white;
  ctx.font = "bold 56px -apple-system, 'SF Pro Display', 'Segoe UI', sans-serif";
  ctx.textAlign = "left";
  ctx.fillText("Alkemos", 100, 130);

  // Tool name
  ctx.fillStyle = "#a1a1a6";
  ctx.font = "400 28px -apple-system, 'SF Pro Display', sans-serif";
  ctx.fillText(isAr ? meta.nameAr : meta.nameEn, 100, 180);

  // Date (right side)
  ctx.textAlign = "right";
  ctx.fillStyle = "#a1a1a6";
  ctx.font = "400 22px -apple-system, sans-serif";
  const dateStr = new Date().toLocaleDateString(isAr ? "ar-EG" : "en-US", {
    year: "numeric",
    month: "short",
    day: "numeric",
  });
  ctx.fillText(dateStr, W - 100, 130);

  // === Big headline metric (centered) ===
  const formatted = meta.format(resultData, isAr);

  ctx.textAlign = "center";
  ctx.fillStyle = COLORS.primary;
  ctx.font = "bold 200px -apple-system, 'SF Pro Display', sans-serif";
  ctx.fillText(formatted.headline, W / 2, 480);

  // Sub-label
  ctx.fillStyle = COLORS.subtext;
  ctx.font = "400 36px -apple-system, sans-serif";
  ctx.fillText(formatted.sublabel, W / 2, 540);

  // === Title row (small, above the headline area) ===
  if (title) {
    ctx.fillStyle = COLORS.text;
    ctx.font = "600 28px -apple-system, sans-serif";
    const titleLines = wrapText(ctx, title, W - 200);
    let y = 320;
    for (const line of titleLines.slice(0, 2)) {
      ctx.fillText(line, W / 2, y);
      y += 36;
    }
  }

  // === Stats grid ===
  const rows = formatted.rows;
  const rowH = 130;
  const startY = 680;
  const padding = 60;
  const cardW = W - 2 * padding;

  for (let i = 0; i < rows.length; i++) {
    const [label, value] = rows[i];
    const y = startY + i * (rowH + 20);

    // Card background
    ctx.fillStyle = COLORS.cardBg;
    drawRoundedRect(ctx, padding, y, cardW, rowH, 24);
    ctx.fill();

    // Label (left)
    ctx.textAlign = "left";
    ctx.fillStyle = COLORS.subtext;
    ctx.font = "400 32px -apple-system, sans-serif";
    ctx.fillText(label, padding + 40, y + rowH / 2 + 12);

    // Value (right)
    ctx.textAlign = "right";
    ctx.fillStyle = COLORS.text;
    ctx.font = "600 40px -apple-system, sans-serif";
    ctx.fillText(value, padding + cardW - 40, y + rowH / 2 + 14);
  }

  // === Footer ===
  // Footer shows "Generated by Alkemos — alkemos.com"
  // where "Alkemos" is the visible brand name (linked to the site
  // URL when rendered as clickable HTML; in image/PDF it's just text).
  ctx.textAlign = "center";
  ctx.fillStyle = COLORS.subtext;
  ctx.font = "400 24px -apple-system, sans-serif";
  ctx.fillText(
    isAr
      ? "تم الإنشاء بواسطة Alkemos — alkemos.com"
      : "Generated by Alkemos — alkemos.com",
    W / 2,
    H - 80,
  );

  return canvas;
}

/**
 * Export the result card as a PNG image and trigger download.
 */
export async function exportResultPng({
  toolSlug,
  title,
  resultData,
  isAr,
}: ExportArgs): Promise<void> {
  const canvas = drawResultCanvas({ toolSlug, title, resultData, isAr });

  // Convert to PNG and trigger download
  const blob: Blob = await new Promise((resolve, reject) => {
    canvas.toBlob(
      (b) => (b ? resolve(b) : reject(new Error("toBlob failed"))),
      "image/png",
      0.95,
    );
  });

  const url = URL.createObjectURL(blob);
  const a = document.createElement("a");
  a.href = url;
  a.download = `${toolSlug}-result-${Date.now()}.png`;
  document.body.appendChild(a);
  a.click();
  document.body.removeChild(a);
  setTimeout(() => URL.revokeObjectURL(url), 1000);
}

/**
 * Export the result card as a PDF document and trigger download.
 *
 * Implementation: draw the same result card onto a canvas, encode as
 * JPEG (natively supported in PDF via /DCTDecode filter — no predictor
 * params needed), then embed in a minimal single-page PDF document.
 *
 * The PDF is a single page sized to match the canvas aspect ratio
 * (4:5 portrait, ~540×675pt). All text in the image (including the
 * footer "Generated by Alkemos — alkemos.com") is part of
 * the rasterized image, so it appears correctly when viewed or printed.
 */
export async function exportResultPdf({
  toolSlug,
  title,
  resultData,
  isAr,
}: ExportArgs): Promise<void> {
  const canvas = drawResultCanvas({ toolSlug, title, resultData, isAr });

  // Step 1: encode the canvas as JPEG (white background so transparency
  // doesn't make text invisible — we explicitly filled the canvas with
  // COLORS.bg in drawResultCanvas).
  const jpegBlob = await new Promise<Blob>((resolve, reject) => {
    canvas.toBlob(
      (b) => (b ? resolve(b) : reject(new Error("canvas.toBlob failed"))),
      "image/jpeg",
      0.92,
    );
  });

  // Step 2: wrap the JPEG bytes in a minimal single-page PDF
  const pdfBlob = await wrapJpegInPdf(jpegBlob, W, H);

  // Step 3: trigger download
  const url = URL.createObjectURL(pdfBlob);
  const a = document.createElement("a");
  a.href = url;
  a.download = `${toolSlug}-result-${Date.now()}.pdf`;
  document.body.appendChild(a);
  a.click();
  document.body.removeChild(a);
  setTimeout(() => URL.revokeObjectURL(url), 1000);
}

/**
 * Wrap a JPEG image as a single-page PDF document.
 *
 * Constructs a minimal valid PDF 1.4 with:
 *   - 1 Catalog (root)
 *   - 1 Pages (page tree)
 *   - 1 Page (single page, MediaBox matches the image aspect ratio)
 *   - 1 Image XObject (the JPEG, embedded as binary stream with
 *     /Filter /DCTDecode — natively supported in PDF, no extra params)
 *   - 1 Content stream (draws the image at full page size)
 *
 * Page size: 540 × 675 pt (7.5 × 9.375 inches) — preserves the canvas
 * 4:5 portrait aspect ratio.
 */
async function wrapJpegInPdf(jpegBlob: Blob, imgPxW: number, imgPxH: number): Promise<Blob> {
  const jpegBytes = new Uint8Array(await jpegBlob.arrayBuffer());

  // PDF page dimensions in points (1 pt = 1/72 inch).
  // 540×675 pt = 7.5×9.375 inches, matching canvas 4:5 aspect.
  const pageW = 540;
  const pageH = 675;

  const pdfContent: number[] = [];
  const offsets: number[] = [];

  const pushAscii = (s: string) => {
    for (let i = 0; i < s.length; i++) pdfContent.push(s.charCodeAt(i) & 0xff);
  };
  const pushBytes = (b: Uint8Array) => {
    for (let i = 0; i < b.length; i++) pdfContent.push(b[i]);
  };
  const markOffset = () => offsets.push(pdfContent.length);

  // PDF header
  pushAscii("%PDF-1.4\n");
  // Binary marker comment (signals the file is binary, not pure ASCII)
  pdfContent.push(0x25, 0xe2, 0xe3, 0xcf, 0xd3, 0x0a);

  // Object 1: Catalog
  markOffset();
  pushAscii("1 0 obj\n<< /Type /Catalog /Pages 2 0 R >>\nendobj\n");

  // Object 2: Pages (page tree root)
  markOffset();
  pushAscii("2 0 obj\n<< /Type /Pages /Kids [3 0 R] /Count 1 >>\nendobj\n");

  // Object 3: Page
  markOffset();
  pushAscii(
    `3 0 obj\n<< /Type /Page /Parent 2 0 R /MediaBox [0 0 ${pageW} ${pageH}] ` +
    `/Contents 5 0 R /Resources << /XObject << /Im1 4 0 R >> >> >>\nendobj\n`,
  );

  // Object 4: Image XObject (JPEG, embedded raw with /DCTDecode filter)
  markOffset();
  const imgHeader =
    `4 0 obj\n<< /Type /XObject /Subtype /Image /Width ${imgPxW} /Height ${imgPxH} ` +
    `/ColorSpace /DeviceRGB /BitsPerComponent 8 ` +
    `/Filter /DCTDecode /Length ${jpegBytes.length} >>\nstream\n`;
  pushAscii(imgHeader);
  pushBytes(jpegBytes);
  pushAscii("\nendstream\nendobj\n");

  // Object 5: Content stream — draws the image at full page size
  // q = save graphics state, cm = concat matrix (scale + translate),
  // /Im1 Do = draw image XObject named Im1, Q = restore state
  const contentStream = `q\n${pageW} 0 0 ${pageH} 0 0 cm\n/Im1 Do\nQ\n`;
  markOffset();
  pushAscii(
    `5 0 obj\n<< /Length ${contentStream.length} >>\nstream\n${contentStream}endstream\nendobj\n`,
  );

  // XRef table
  const xrefOffset = pdfContent.length;
  pushAscii(`xref\n0 ${offsets.length + 1}\n`);
  pushAscii("0000000000 65535 f \n");
  for (const off of offsets) {
    pushAscii(off.toString().padStart(10, "0") + " 00000 n \n");
  }

  // Trailer
  pushAscii(
    `trailer\n<< /Size ${offsets.length + 1} /Root 1 0 R >>\nstartxref\n${xrefOffset}\n%%EOF\n`,
  );

  return new Blob([new Uint8Array(pdfContent)], { type: "application/pdf" });
}
